public class MakeColumnQueuesTests {

    private TextHelpAppendable textHelpAppendable;
    private Method makeColumnQueuesMethod;

    @Before
    public void setUp() throws Exception {
        textHelpAppendable = new TextHelpAppendable(new StringBuilder());
        makeColumnQueuesMethod = TextHelpAppendable.class.getDeclaredMethod(
            "makeColumnQueues", 
            List.class, 
            List.class
        );
        makeColumnQueuesMethod.setAccessible(true);
    }

    @Test
    public void testMakeColumnQueuesEmptyInput() throws Exception {
        List<String> columnData = new ArrayList<>();
        List<TextStyle> styles = new ArrayList<>();

        List<Queue<String>> result = (List<Queue<String>>) makeColumnQueuesMethod.invoke(
            textHelpAppendable, columnData, styles);

        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

