        List<TextStyle> styles = new ArrayList<>();
        TextStyle.Builder builder = TextStyle.builder();
        builder.setMaxWidth(20);
        builder.setLeftPad(1);
        builder.setIndent(3);
        TextStyle style = builder.getStyle();
        styles.add(style);

        List<Queue<String>> result = (List<Queue<String>>) makeColumnQueuesMethod.invoke(
            textHelpAppendable, columnData, styles);

        assertNotNull(result);
        assertEquals(1, result.size());
        assertNotNull(result.get(0));
        assertEquals(1, result.get(0).size());
