import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import org.junit.runners.Parameterized.Parameters;

import java.util.Arrays;
import java.util.Collection;

import static org.junit.Assert.assertEquals;

@RunWith(Parameterized.class)
public class PadTests {

    private TextStyle textStyle;
    private final int maxWidth;
    private final int indent;
    private final TextStyle.Alignment alignment;

    public PadTests(int maxWidth, int indent, TextStyle.Alignment alignment) {
        this.maxWidth = maxWidth;
        this.indent = indent;
        this.alignment = alignment;
    }

    @Parameters(name = "maxWidth={0}, indent={1}, alignment={2}")
    public static Collection<Object[]> data() {
        return Arrays.asList(new Object[][] {
            // Test with UNSET_MAX_WIDTH
            {TextStyle.UNSET_MAX_WIDTH, 4, TextStyle.Alignment.LEFT},
            {TextStyle.UNSET_MAX_WIDTH, 4, TextStyle.Alignment.RIGHT},
            {TextStyle.UNSET_MAX_WIDTH, 4, TextStyle.Alignment.CENTER},

            // Test with specific maxWidth
            {20, 4, TextStyle.Alignment.LEFT},
            {20, 4, TextStyle.Alignment.RIGHT},
            {20, 4, TextStyle.Alignment.CENTER},

            // Edge cases
            {5, 0, TextStyle.Alignment.LEFT},
            {5, 0, TextStyle.Alignment.RIGHT},
            {5, 0, TextStyle.Alignment.CENTER},

            // Large indent
            {20, 15, TextStyle.Alignment.LEFT},
            {20, 15, TextStyle.Alignment.RIGHT},
            {20, 15, TextStyle.Alignment.CENTER}
        });
    }

    @Before
    public void setUp() {
        textStyle = TextStyle.builder()
            .setMaxWidth(maxWidth)
            .setIndent(indent)
            .setAlignment(alignment)
            .get();
    }

    @Test
    public void testPadWithTextLongerThanMaxWidth() {
        String longText = "This is a very long text that exceeds max width";
        String result = textStyle.pad(true, longText).toString();
        assertEquals(longText, result);
    }

    @Test
    public void testPadWithAddIndentTrue() {
        String text = "test";
        String result = textStyle.pad(true, text).toString();

        if (maxWidth == TextStyle.UNSET_MAX_WIDTH) {
            if (alignment == TextStyle.Alignment.CENTER) {
                // For CENTER with UNSET_MAX_WIDTH, only indent is added
                int expectedPad = indent;
                int left = expectedPad / 2;
                String expected = repeatSpace(left) + text + repeatSpace(expectedPad - left);
                assertEquals(expected, result);
            } else {
                // For LEFT/RIGHT with UNSET_MAX_WIDTH, only indent is added
                String expected = repeatSpace(indent) + text;
                if (alignment == TextStyle.Alignment.RIGHT) {
                    expected = text + repeatSpace(indent);
                }
                assertEquals(expected, result);
            }
        } else {
            if (text.length() < maxWidth) {
                if (alignment == TextStyle.Alignment.CENTER) {
                    int padLen = maxWidth - text.length();
                    int left = padLen / 2;
                    String expected = repeatSpace(left) + text + repeatSpace(padLen - left);
                    assertEquals(expected, result);
                } else {
                    int restLen = maxWidth - text.length();
                    if (restLen > indent) {
                        String expected = repeatSpace(indent) + text + repeatSpace(restLen - indent);
                        if (alignment == TextStyle.Alignment.RIGHT) {
                            expected = repeatSpace(indent) + repeatSpace(restLen - indent) + text;
                        }
                        assertEquals(expected, result);
                    } else {
                        String expected = text + repeatSpace(restLen);
                        if (alignment == TextStyle.Alignment.RIGHT) {
                            expected = repeatSpace(restLen) + text;
                        }
                        assertEquals(expected, result);
                    }
                }
            }
        }
    }

    @Test
    public void testPadWithAddIndentFalse() {
        String text = "test";
        String result = textStyle.pad(false, text).toString();

        if (maxWidth == TextStyle.UNSET_MAX_WIDTH) {
            if (alignment == TextStyle.Alignment.CENTER) {
                // No padding when no indent and UNSET_MAX_WIDTH
                assertEquals(text, result);
            } else {
                // No padding when no indent and UNSET_MAX_WIDTH
                assertEquals(text, result);
            }
        } else {
            if (text.length() < maxWidth) {
                if (alignment == TextStyle.Alignment.CENTER) {
                    int padLen = maxWidth - text.length();
                    int left = padLen / 2;
                    String expected = repeatSpace(left) + text + repeatSpace(padLen - left);
                    assertEquals(expected, result);
                } else {
                    int restLen = maxWidth - text.length();
                    String expected = text + repeatSpace(restLen);
                    if (alignment == TextStyle.Alignment.RIGHT) {
                        expected = repeatSpace(restLen) + text;
                    }
                    assertEquals(expected, result);
                }
            } else {
                assertEquals(text, result);
            }
        }
    }

    @Test
    public void testPadEmptyString() {
        String text = "";
        String result = textStyle.pad(true, text).toString();

        if (maxWidth == TextStyle.UNSET_MAX_WIDTH) {
            if (alignment == TextStyle.Alignment.CENTER) {
                int expectedPad = indent;
                int left = expectedPad / 2;
                String expected = repeatSpace(left) + text + repeatSpace(expectedPad - left);
                assertEquals(expected, result);
            } else {
                String expected = repeatSpace(indent) + text;
                if (alignment == TextStyle.Alignment.RIGHT) {
                    expected = text + repeatSpace(indent);
                }
                assertEquals(expected, result);
            }
        } else {
            if (alignment == TextStyle.Alignment.CENTER) {
                int padLen = maxWidth;
                int left = padLen / 2;
                String expected = repeatSpace(left) + text + repeatSpace(padLen - left);
                assertEquals(expected, result);
            } else {
                int restLen = maxWidth;
                if (restLen > indent) {
                    String expected = repeatSpace(indent) + text + repeatSpace(restLen - indent);
                    if (alignment == TextStyle.Alignment.RIGHT) {
                        expected = repeatSpace(indent) + repeatSpace(restLen - indent) + text;
                    }
                    assertEquals(expected, result);
                } else {
                    String expected = text + repeatSpace(restLen);
                    if (alignment == TextStyle.Alignment.RIGHT) {
                        expected = repeatSpace(restLen) + text;
                    }
                    assertEquals(expected, result);
                }
            }
        }
    }

    @Test
    public void testPadWithExactMaxWidth() {
        if (maxWidth != TextStyle.UNSET_MAX_WIDTH) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < maxWidth; i++) {
                sb.append("x");
            }
            String text = sb.toString();
            String result = textStyle.pad(true, text).toString();
            assertEquals(text, result);
        }
    }

    private String repeatSpace(int count) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            sb.append(' ');
        }
        return sb.toString();
    }
}

